import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The TUI desktop","description":"","frontmatter":{},"headers":[],"relativePath":"manual/tui-guide.md","filePath":"manual/tui-guide.md"}'),d={name:"manual/tui-guide.md"};function i(o,e,h,n,c,l){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="the-tui-desktop" tabindex="-1">The TUI desktop <a class="header-anchor" href="#the-tui-desktop" aria-label="Permalink to &quot;The TUI desktop&quot;">​</a></h1><h2 id="starting-it" tabindex="-1">Starting it <a class="header-anchor" href="#starting-it" aria-label="Permalink to &quot;Starting it&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; tui</span></span></code></pre></div><p>The desktop takes the graphical console (run QEMU with <code>-vga std</code>); the serial line keeps the ush prompt for parallel access.</p><h2 id="the-screen" tabindex="-1">The screen <a class="header-anchor" href="#the-screen" aria-label="Permalink to &quot;The screen&quot;">​</a></h2><ul><li>the <strong>panel</strong> at the top: clock, power, system summary</li><li>the <strong>desktop</strong> center: the app launcher</li><li>the <strong>taskbar</strong>: running TUI apps, the launcher button</li></ul><p>Keyboard model: arrows + Enter navigate, ESC backs out, the menu key opens the launcher. The mouse is not required - every action is reachable from the keyboard (the input contract the accessibility gate asserts).</p><h2 id="the-built-in-tui-apps" tabindex="-1">The built-in TUI apps <a class="header-anchor" href="#the-built-in-tui-apps" aria-label="Permalink to &quot;The built-in TUI apps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>What it does</th></tr></thead><tbody><tr><td>tui-files</td><td>browse / copy / move / delete, launch edit</td></tr><tr><td>tui-editor</td><td>the same editor core the <code>edit</code> command uses, framed</td></tr><tr><td>tui-proc</td><td>the process table (the <code>ps</code> data)</td></tr><tr><td>tui-apps</td><td>the app launcher / registry browser</td></tr><tr><td>tui-time</td><td>clocks (RTC / HPET / TSC)</td></tr><tr><td>tui-net</td><td>network status surfaces</td></tr><tr><td>tui-sysinfo / tui-hw / tui-drv / tui-sys</td><td>hardware + system pages</td></tr></tbody></table><h2 id="the-tui-command-family" tabindex="-1">The TUI command family <a class="header-anchor" href="#the-tui-command-family" aria-label="Permalink to &quot;The TUI command family&quot;">​</a></h2><p><code>tui</code> (desktop), <code>tui-test</code> (the selftests), <code>tui-hw</code>, <code>tui-net</code>, <code>tui-sysinfo [page]</code>, <code>tui-time</code>, <code>tui-drv [page]</code>, <code>tui-sys [page]</code>, <code>tui-ext</code> - all registry programs, all also reachable through the shell while the desktop runs.</p><h2 id="tui-and-the-merged-apps" tabindex="-1">TUI and the merged apps <a class="header-anchor" href="#tui-and-the-merged-apps" aria-label="Permalink to &quot;TUI and the merged apps&quot;">​</a></h2><p>The TUI renders the same services the 8 merged apps wrap - the sysinfo pages read the same L1SVC ops <code>hwinfo</code> does. The desktop is a viewer; the wizard apps are the operator surface; the classic commands are the scripting surface - three doors, one system.</p>',13)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
